import {parseMFFT,objects,value,values,field,clone,pinsFor,compile,decodeSymbol} from './engine.js';
const quoted=s=>JSON.stringify(String(s??''));
export const normalizedReference=s=>String(s).replace(/^\(1\)(.*?):\(2\)(.*)$/,'$1/$2').replace(/^PRIMITIV(?:E)?\//i,'PRIMITIVE/').toUpperCase();
export function decodeNetlist(text,key){
 const all=objects(parseMFFT(text)),byId=new Map(all.map(o=>[value(o,'OBJECTXID'),o])),nets=all.filter(o=>/^NVNet/.test(value(o,'OBJECTTYPE',''))),parent=new Map();
 const root=id=>{if(!parent.has(id))parent.set(id,id);if(parent.get(id)!==id)parent.set(id,root(parent.get(id)));return parent.get(id);};
 for(const n of nets){const ids=[...values(n,'JoinedPorts'),...values(n,'JoinedInstPorts')];if(ids.length)for(const id of ids)parent.set(root(id),root(ids[0]));}
 const point=id=>{const r=root(id);return [r*10,r*10];};
 const components=all.filter(o=>value(o,'OBJECTTYPE')==='NVPortScalar').map(o=>{const p=point(value(o,'OBJECTXID'));return {id:'p'+value(o,'OBJECTXID'),name:value(o,'OBJECTNAME'),kind:value(o,'Direction')===1?'INPUT':'OUTPUT',x:p[0],y:p[1]};});
 for(const o of all.filter(o=>value(o,'OBJECTTYPE')==='NVInst')){const ports=values(o,'InstPorts').map(id=>byId.get(id)).filter(Boolean);components.push({id:'i'+value(o,'OBJECTXID'),name:value(o,'OBJECTNAME'),kind:'GATE',symbol:normalizedReference(value(o,'DescriberName','')),x:0,y:0,pins:ports.map(p=>({name:value(p,'OBJECTNAME'),direction:value(p,'Direction'),end:[point(value(p,'OBJECTXID'))[0],-point(value(p,'OBJECTXID'))[1]]})),portBubbles:ports.filter(p=>value(p,'IsBubble')==='TRUE').map(p=>value(p,'OBJECTNAME'))});}
 return {name:key,library:key.split('/')[0],components,wires:[],notes:[],virtual:true};
}
export function encodeMFFT(circuit,data){
 let xid=1;const ids=new Map(),connection=p=>{const key=p.join(',');if(!ids.has(key))ids.set(key,100000+ids.size);return ids.get(key);};
 const scalar=(k,t,...v)=>`  (${k} (${t} ${v.map(x=>typeof x==='string'&&t==='STRING'?quoted(x):x).join(' ')}))`;
 const object=(type,name,body)=>`(OBJECT\n${scalar('OBJECTTYPE','STRING',type)}\n${scalar('OBJECTNAME','STRING',name)}\n${scalar('OBJECTXID','XID',xid++)}\n${body}\n)`;
 const display=(name,x,y)=>`  (DisplayInfo (Name (STRING "Name")) (Value (STRING ${quoted(name)})) (Position (INT ${x} ${y})) (OriginalPosition (INT 0 0)) (DisplayMode (INT 2)) (DisplayType (INT 0)) (DisplayAttr (INT 2)) (FontHeight (INT 15)) (FontAlign (INT 0)) (FontAngle (INT 0)) (Color (INT 0 0 0)) (EditType (INT 1)))`;
 const list=[];
 for(const c of circuit.components){let body=scalar('Color','INT',0,0,255)+'\n'+scalar('Transform','INT',c.rotation||0,c.mirror?-1:1,c.x,-c.y);if(c.kind==='GATE'){body+='\n'+scalar('DescriberName','STRING',c.symbol+'/symbol')+'\n'+scalar('SimulationModel','INT',0);for(const p of pinsFor(c,data))body+=`\n  (InstPort (Name (STRING ${quoted(p.name)})) (Bubble (BOOLEAN ${(c.portBubbles||[]).includes(p.name)?'TRUE':'FALSE'})))`;body+='\n'+display(c.name,c.x,-c.y-20);}else body+='\n'+scalar('Direction','INT',c.kind==='INPUT'?1:2)+'\n'+scalar('Connection','INT',connection([c.x,c.y]))+'\n'+display(c.name,c.x+(c.kind==='INPUT'?-40:25),-c.y+10);list.push(object(c.kind==='GATE'?'InstImp':'Port',c.name,body));}
 for(const w of circuit.wires)list.push(object('NetSegment',w.name||'',scalar('Color','INT',128,0,0)+`\n  (Path (Size (INT ${w.points.length})) (Points (INT ${w.points.flatMap(p=>[p[0],-p[1]]).join(' ')})))\n`+scalar('FirstConnection','INT',connection(w.points[0]))+'\n'+scalar('SecondConnection','INT',connection(w.points.at(-1)))));
 for(const f of circuit.figures||[]){let body=scalar('Color','INT',0,0,0);if(f.kind==='Text')body+='\n'+scalar('Position','INT',f.x,-f.y)+'\n'+scalar('Content','STRING',f.text)+'\n'+scalar('Height','INT',f.size||15)+'\n'+scalar('Align','INT',0);else if(f.kind==='Line'||f.kind==='Arc')body+='\n'+scalar('StartPoint','INT',f.x,-f.y)+'\n'+scalar('EndPoint','INT',f.x2,-f.y2)+(f.kind==='Arc'?'\n'+scalar('ControlPoint','INT',(f.x+f.x2)/2,-Math.min(f.y,f.y2)-Math.abs(f.x2-f.x)/2):'');else body+='\n'+scalar('BoundRect','INT',f.x,-f.y,f.x2,-f.y2);list.push(object(f.kind,'NoName',body));}
 return `[MFFT1.00-schematic-V300]\n(libName (STRING ${quoted(circuit.library||'User')}))\n(cellName (STRING ${quoted(circuit.name)}))\n(viewName (STRING "schematic"))\n${list.join('\n')}\n`;
}
export function makeSymbol(circuit,name){
 const ins=circuit.components.filter(c=>c.kind==='INPUT'),outs=circuit.components.filter(c=>c.kind==='OUTPUT');if(!ins.length||!outs.length)throw Error('입력과 출력 포트가 필요합니다.');if(new Set([...ins,...outs].map(c=>c.name)).size!==ins.length+outs.length)throw Error('포트 이름이 중복됩니다.');
 const h=Math.max(60,Math.max(ins.length,outs.length)*20+20),obj=(type,body)=>`(OBJECT (OBJECTTYPE (STRING "${type}")) ${body})`,graphics=[obj('Rect',`(BoundRect (INT -60 ${h/2} 60 ${-h/2}))`),obj('Text',`(Position (INT 0 ${h/2+15})) (Height (INT 15)) (Align (INT 1)) (Content (STRING ${quoted(name)}))`)];
 for(const [ports,direction] of [[ins,1],[outs,2]])ports.forEach((p,i)=>{const x=direction===1?-60:60,y=((ports.length-1)/2-i)*20,end=x+(direction===1?-20:20);graphics.push(obj('SymbolPort',`(Direction (INT ${direction})) (StartPoint (INT ${x} ${y})) (EndPoint (INT ${end} ${y})) (Bubble (BOOLEAN FALSE)) (DisplayInfo (Name (STRING "Name")) (Value (STRING ${quoted(p.name)})) (Position (INT ${direction===1?-50:50} ${y+3})) (FontHeight (INT 10)) (FontAlign (INT ${direction===1?0:2})) (DisplayMode (INT 2)))`));});
 const text=`[MFFT1.00-symbol-V300]\n(cellName (STRING ${quoted(name)}))\n${graphics.join('\n')}`;return {symbol:decodeSymbol(text,'USER/'+name.toUpperCase()),text};
}
export function copyCircuitSelection(circuit,ids,data){const selected=new Set(ids),components=circuit.components.filter(c=>selected.has(c.id)),wireSelected=circuit.wires.filter(w=>selected.has(w.id));if(components.length===circuit.components.length)return clone({components,wires:circuit.wires,figures:circuit.figures||[]});const graph=compile(circuit,data),inside=new Set([...graph.nets].filter(([,pins])=>pins.length&&pins.every(p=>selected.has(p.component))).map(([net])=>net));return clone({components,wires:circuit.wires.filter(w=>inside.has(graph.root(w.points[0]))||wireSelected.includes(w)),figures:(circuit.figures||[]).filter(f=>selected.has(f.id))});}
export function pasteCircuitSelection(circuit,clipboard,offset=[40,40],nextId=()=>crypto.randomUUID()){
 const out=clone(clipboard),taken=new Set(circuit.components.map(c=>c.name)),unique=n=>{let name=n,i=1;while(taken.has(name))name=n+'_'+i++;taken.add(name);return name;};for(const c of out.components){c.id=nextId();c.name=unique(c.name);c.x+=offset[0];c.y+=offset[1];}for(const w of out.wires){w.id=nextId();w.points=w.points.map(p=>[p[0]+offset[0],p[1]+offset[1]]);}for(const f of out.figures||[]){f.id=nextId();f.x+=offset[0];f.y+=offset[1];if(f.x2!==undefined){f.x2+=offset[0];f.y2+=offset[1];}}return out;
}
export function parseStimulus(text,names){const s={maxTime:1000,clocks:{},events:{},vectors:{},watch:[]};text=text.replace(/^\[[^\]]*\]/,'').replace(/\/\/[^\n]*/g,'');const exists=n=>{if(!names.includes(n))throw Error('존재하지 않는 입력: '+n);};for(const line of text.split(';').map(s=>s.trim()).filter(Boolean)){let m;if((m=line.match(/^MAX_TIME\s+(\d+)$/i))){s.maxTime=+m[1];continue;}if((m=line.match(/^CLOCK\s+(\S+)\s+FROM\s*:\s*(\d+)\s+TO\s*:\s*(\d+)\s+STEPSIZE\s*:\s*(\d+)\s+([01XZ\s]+)$/i))){exists(m[1]);const v={start:+m[2],end:+m[3],step:+m[4],values:m[5].trim().toUpperCase().split(/\s+/).map(v=>/[01]/.test(v)?+v:v)};if(!v.step||v.end<v.start)throw Error('CLOCK 시간 범위를 확인하세요.');s.clocks[m[1]]=v;continue;}if((m=line.match(/^GEN\s+(\S+)\s+(.+)$/i))){exists(m[1]);const events=m[2].trim().toUpperCase().split(/[\s,]+/).map(e=>{const p=e.match(/^([01XZ])@(\d+)$/);if(!p)throw Error('GEN 문법: 0@0 1@10 X@100');return {time:+p[2],value:/[01]/.test(p[1])?+p[1]:p[1]};});s.events[m[1]]=[...(s.events[m[1]]||[]),...events].sort((a,b)=>a.time-b.time);continue;}if((m=line.match(/^VECTOR\s+(\S+)\s+(.+)$/i))){s.vectors[m[1]]=m[2].trim().split(/\s+/);continue;}if((m=line.match(/^WATCH\s+(.+)$/i))){s.watch=m[1].trim().split(/\s+/);continue;}throw Error('지원하지 않거나 잘못된 입력 문법: '+line);}if(s.maxTime<1)throw Error('MAX_TIME은 1 이상이어야 합니다.');return s;}
export function stimulusAt(s,time,previous={}){const inputs={...previous};for(const [n,c]of Object.entries(s.clocks)){if(time>=c.start&&time<=c.end)inputs[n]=c.values[Math.floor((time-c.start)/c.step)%c.values.length];}for(const [n,ev]of Object.entries(s.events)){const applicable=ev.filter(e=>e.time<=time).at(-1);if(applicable){const clock=s.clocks[n],lastClock=clock&&time>=clock.start&&time<=clock.end?clock.start+Math.floor((time-clock.start)/clock.step)*clock.step:-1;if(applicable.time>=lastClock)inputs[n]=applicable.value;}}return inputs;}
export function exportVCD(history,signals,name='Logic Forge'){const ids=signals.map((_,i)=>'s'+i),header=`$version ${name} $end\n$timescale 1ns $end\n$scope module circuit $end\n${signals.map((n,i)=>`$var wire 1 ${ids[i]} ${n.replace(/\s+/g,'_')} $end`).join('\n')}\n$upscope $end\n$enddefinitions $end\n`;return header+history.map(s=>`#${s.time}\n`+signals.map((n,i)=>String(s.values[n]??'X').toLowerCase()+ids[i]).join('\n')).join('\n')+'\n';}
